def is_woodall(n):
    # A number is considered woodall if it can be expressed in the form 2^i - 1 for some i
    # and also if it is of the form 2^j + 2^k - 1 for some j > k >= 0
    if n == 1:
        return True
    i = 0
    while (1 << i) - 1 <= n:
        i += 1
    if i > 0 and (n + 1) & (1 << (i - 1)) == 0:
        return True
    return False
```

