def bell_number(n):
    # Initialize a list to store the number of ways to partition sets of size i
    bell = [0] * (n + 1)
    bell[0] = 1  # Base case: there's one way to partition a set of size 0

    # Fill the bell array using the recursive formula
    for i in range(1, n + 1):
        bell[i] = sum(bell[j] * catalan(j) for j in range(i))

    return bell[n]

# Helper function to calculate Catalan number (used in the recursive formula)
def catalan(n):
    if n == 0:
        return 1
    else:
        return binomial(2 * n, n) // (n + 1)

# Helper function to calculate binomial coefficient
def binomial(n, k):
    if k > n - k:
        k = n - k
    res = 1
    for i in range(k):
        res *= (n - i)
        res //= (i + 1)
    return res
```

