def comb_sort(arr):
    gap = len(arr)
    sorted = False

    while not sorted:
        gap = max(1, int(gap / 1.3))  # Shrink gap
        sorted = False
        for i in range(len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]  # Swap elements
                sorted = False  # Not sorted, keep shrinking
            else:
                sorted = True  # Sorted, no more swaps needed

    return arr
```

