def is_undulating(num):
    # Convert the number to a string to easily iterate over its digits
    num_str = str(num)
    # Check if the length of the number is less than 3, which cannot be undulating
    if len(num_str) < 3:
        return False
    # Check if the first and last digits are the same
    if num_str[0] != num_str[-1]:
        return False
    # Check if the number is of the form 121212... or 199199...
    for i in range(1, len(num_str) - 1, 2):
        if num_str[i] != num_str[i + 1] or num_str[i] != num_str[i + 2]:
            return False
    return True
```

