def extract_missing(intervals, start, end):
    missing_ranges = []
    for start_interval, end_interval in intervals:
        # If the interval starts after the start range, add the missing range from start to start_interval - 1
        if start_interval > start:
            missing_ranges.append((start, start_interval - 1))
        # If the interval ends before the end range, add the missing range from end_interval + 1 to end
        if end_interval < end:
            missing_ranges.append((end_interval + 1, end))
    # Add missing ranges for the start and end of the full range
    if start < intervals[0][0]:
        missing_ranges.append((start, intervals[0][0] - 1))
    if intervals[-1][1] < end:
        missing_ranges.append((intervals[-1][1] + 1, end))
    return missing_ranges
```

