def solution(a, b, n):
    if a * b == 0:
        if n % a == 0:
            return f'x = {n // a}, y = 0'
        elif n % b == 0:
            return f'x = 0, y = {n // b}'
        else:
            return 'No solution'

    gcd = gcd(a, b)
    if n % gcd != 0:
        return 'No solution'

    x = n // b * (b // gcd)
    y = n // a * (a // gcd)

    if a * x + b * y != n:
        return 'No solution'

    return f'x = {x}, y = {y}'

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x
