        return arr[0]
    if high == low:
        return arr[low]
    mid = low + (high - low) // 2
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid + 1]
    if mid > low and arr[mid] < arr[mid - 1]:
