def max_sum(triangle, n):
    # Initialize a 2D list to store the maximum sums
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Base case: the maximum sum for the first row is the value itself
    for i in range(n):
        dp[0][i] = triangle[0][i]

    # Fill the dp table
    for i in range(1, n):
        for j in range(i + 1):
            if j == 0:
                dp[i][j] = dp[i-1][j] + triangle[i][j]
            elif j == i:
                dp[i][j] = dp[i-1][j-1] + triangle[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1]) + triangle[i][j]

    # Find the maximum sum in the last row
    return max(dp[n-1])
```

