        if first_element in occurrences:
            occurrences[first_element] += 1
        else:
            occurrences[first_element] = 1

    # Sort the list based on the occurrences
    sorted_list = sorted(tuples_list, key=lambda x: occurrences[x[0]], reverse=True)

    # Reconstruct the list with the sorted order
    result = []
    for tup in sorted_list:
        result.append(tup)
        if tup[0] in occurrences and occurrences[tup[0]] > 1:
            result.append(occurrences[tup[0]])

    return result
