def minimum_Length(s):
    # If the string is empty, return 0
    if not s:
        return 0

    # If the string has only one character, return 1
    if len(s) == 1:
        return 1

    # Iterate through the string to find the character that can be removed
    # to minimize the length of the string
    for char in set(s):
        new_str = s.replace(char, '')
        if len(new_str) < len(s):
            return len(new_str)

    # If no character can be removed, the string is already minimal
    return len(s)
```

