def permute_string(s):
    def permute(s, l, r, temp):
        if l == r:
            result.append(''.join(temp))
        else:
            for i in range(l, r + 1):
                temp[l], temp[i] = temp[i], temp[l]
                permute(s, l + 1, r, temp)
                temp[l], temp[i] = temp[i], temp[l]  # backtrack

    result = []
    temp = list(s)
    permute(s, 0, len(s) - 1, temp)
    return result
```

