def ncr_modp(n, r, p):
    def mod_inverse(x, p):
        """Compute the modular multiplicative inverse of x modulo p using Fermat's little theorem."""
        return pow(x, p - 2, p)

    def mod_factorial(n, p):
        """Compute n! modulo p using a loop to avoid overflow."""
        result = 1
        for i in range(1, n + 1):
            result = (result * i) % p
        return result

    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    numerator = mod_factorial(n, p)
    denominator = (mod_factorial(r, p) * mod_factorial(n - r, p)) % p
    return (numerator * mod_inverse(denominator, p)) % p
```

