def get_maxgold(mines, rows, cols):
    def dfs(x, y, mine):
        if x < 0 or x >= rows or y < 0 or y >= cols or mine[x][y] == 0:
            return 0
        mine[x][y] = 0  # Mark as visited
        return mine[x][y] + dfs(x+1, y, mine) + dfs(x-1, y, mine) + dfs(x, y+1, mine) + dfs(x, y-1, mine)

    max_gold = 0
    for i in range(rows):
        for j in range(cols):
            max_gold = max(max_gold, dfs(i, j, mines))
    return max_gold
```

