def max_product(nums, n):
    dp = [1] * n  # Initialize dp array with 1s
    max_product = nums[0]  # Initialize max_product with the first element

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] * nums[i])
        max_product = max(max_product, dp[i])

    return max_product
```

