def max_profit(prices, k):
    if not prices or k == 0:
        return 0

    n = len(prices)
    if k >= n // 2:
        return sum(max(prices[i] - prices[i-1], 0) for i in range(1, n))

    dp = [[0] * (k+1) for _ in range(n)]

    for i in range(1, n):
        for j in range(1, k+1):
            max_val = -prices[i-1]
            for m in range(j):
                max_val = max(max_val, dp[i-1][m] - prices[i])
            dp[i][j] = max(dp[i-1][j], max_val + prices[i])

    return dp[n-1][k]
```

