def is_subset_sum(arr, n, sum):
    # Initialize a DP table
    dp = [[False for _ in range(sum + 1)] for _ in range(n + 1)]

    # Every subset with sum 0 has value True
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for s in range(1, sum + 1):
            if arr[i - 1] > s:
                dp[i][s] = dp[i - 1][s]
            else:
                dp[i][s] = dp[i - 1][s] or dp[i - 1][s - arr[i - 1]]

    return dp[n][sum]
```

