def no_of_subsequences(arr, k):
    def count_subsequences_with_product_less_than_k(index, current_product):
        if index == len(arr):
            return 1 if current_product < k else 0
        count = 0
        # Include the current element
        count += count_subsequences_with_product_less_than_k(index + 1, current_product * arr[index])
        # Exclude the current element
        count += count_subsequences_with_product_less_than_k(index + 1, current_product)
        return count

    return count_subsequences_with_product_less_than_k(0, 1)
```
